INSERT INTO content_errors (job_id, severity, error_code, error_message, recoverable, context)
SELECT NULLIF('{{$json.job_id}}','')::uuid, 'warning', 'REQUEST_ANALYSIS_PARSE_WARNING', COALESCE(NULLIF('{{$json.warning_message}}',''),'LLM response parse warning'), true, jsonb_build_object('raw_text', LEFT('{{$json.raw_model_text}}', 2000), 'workflow', '{{$json.current_stage}}')
WHERE COALESCE('{{$json.parse_warning}}','false') = 'true';

INSERT INTO content_outputs (job_id, output_type, title, structured_data, qa_status)
VALUES (NULLIF('{{$json.job_id}}','')::uuid, 'request_analysis', 'Request analysis', COALESCE(NULLIF('{{$json.request_analysis_json}}',''),'{}')::jsonb, 'pending');
UPDATE content_jobs SET status='waiting_for_analysis_approval', updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid;
INSERT INTO content_events (job_id,event_type,message,metadata) VALUES (NULLIF('{{$json.job_id}}','')::uuid,'approval_gate','Request analysis approval gate reached',jsonb_build_object('approval_stage','analysis'));
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'waiting_for_analysis_approval' AS status;

