const base = $node['Normalize And Auth'].json;
const current = $json;
const status = current.status || 'waiting_for_analysis_approval';
const results = [...(base.tool_results || []), {tool: 'tool_request_analysis', status, job_id: current.job_id || base.job_id || ''}];
return [{json: {...base, ...current, job_id: current.job_id || base.job_id, status, tool_results: results, current_stage: 'tool_request_analysis'}}];
